items(234,[
I('P000369','definition','Microlocal regularity and the wavefront set',r'For a distribution \(A\), the notes test \(\langle A,\varphi e^{it\psi}\rangle=o(t^{-N})\) for every \(N\), with \(d\psi\) prescribed at one point and arbitrary compactly supported \(\varphi\). Smooth functions have empty wavefront.',r'For \(u\in\mathcal D^{\prime}(M)\), a nonzero covector \((x_0,\xi_0)\) is outside \(\operatorname{WF}(u)\) if, in a coordinate chart, there is a cutoff equal to one near \(x_0\) whose Fourier transform after multiplication by \(u\) decreases faster than every power in an open conic neighbourhood of \(\xi_0\). The wavefront is closed, conic, and projects to the singular support.',r'\citet[\S2.5]{hormander1971fourier} gives the contemporary definition and calculus. The article was printed on 1 June 1971 and developed material circulated in the 1969 Nordic summer-school lectures, before this September talk.',r'the definition is standard. The notebook’s condition requires sufficiently small support and uniform control in neighbouring phase directions; requiring arbitrary support while prescribing \(d\psi\) only at one point is not a valid literal criterion.',literal_correctness='false as written',publication_match='exact',refs=H),
I('P000369','construction','Conormal bundles as Lagrangians',r'A submanifold \(N\subset M\) gives the normal bundle of annihilating covectors, described as a Lagrangian of half the cotangent dimension.',r'For an embedded smooth submanifold \(N\), its conormal bundle \(N^*M=\{(x,\xi):x\in N,\xi|_{T_xN}=0\}\) is Lagrangian in \(T^*M\). The wavefront of a conormal distribution lies in \(N^*M\setminus0\); the Dirac density along a smooth submanifold has precisely this wavefront when its density is nonvanishing.',r'The conormal model is a basic case of the oscillatory constructions in \citet[\S1 and \S3]{hormander1971fourier}. It was established before the seminar.',r'the assertion is standard; ``normal'' here means conormal covectors, without choosing a Riemannian metric.',refs=H),
I('P000369','claim','Pseudodifferential kernels are conormal to the diagonal',r'A pseudodifferential operator is described as a distribution kernel on \(M\times M\) whose wavefront is constructed from the diagonal.',r'The Schwartz kernel of a properly supported pseudodifferential operator of finite order belongs locally to a conormal distribution class for the diagonal; in particular \(\operatorname{WF}(K)\subset N^*\Delta\setminus0\). Wavefront containment alone is not a characterization of the symbol class or of finite operator order.',r'The symbol hypotheses and oscillatory kernel definition are present in \citet[Definition 1.1.1 and the pseudodifferential sections]{hormander1971fourier}. The notebook records the geometric support of singularities but omits their quantitative order.',r'the inclusion is established. A converse needs symbol estimates or equivalent iterated regularity conditions.',refs=H),
I('P000369','claim','Oscillatory parametrization of a Lagrangian distribution',r'The page states that every distribution with wavefront in a Lagrangian is given by an oscillatory integral, and writes a phase-gradient description of \(\Lambda\).',r'A nondegenerate phase \(\phi(x,\theta)\), homogeneous of degree one in \(\theta\), parametrizes \(\Lambda=\{(x,d_x\phi):d_\theta\phi=0\}\). Integrating \(e^{i\phi}a\) against a symbol \(a\) yields a Lagrangian distribution. Membership in \(I^m(M,\Lambda)\) entails amplitude estimates and is strictly stronger than the bare inclusion \(\operatorname{WF}(u)\subset\Lambda\). Locally, members of this class have such representations modulo smooth functions.',r'\citet[\S3]{hormander1971fourier} establishes the phase and amplitude calculus. The notebook collapses the quantitative class condition into a wavefront condition, so its literal universal converse is not the theorem of that paper.',r'the appropriately qualified theorem is established. No new classification problem is inferred from the missing hypotheses.',literal_correctness='false as written',reconstruction=r'The stationary equations \(d_\theta\phi=0\) and the symbol class are supplied; they are essential, not cosmetic.',refs=H)
])
items(235,[
I('P000368','theorem','Affine finite-field Radon inversion by incidence counting',r'For \(f:\mathbb F_q^n\to\mathbb C\), \(\varphi(p)\) sums \(f\) over a ``plane.'' Counting planes through one or two points yields an inversion identity.',r'Let \(n\ge1\), let \(\mathcal H\) be all affine hyperplanes of \(V=\mathbb F_q^n\), and set \(Rf(H)=\sum_{x\in H}f(x)\). Put \(b=(q^{n-1}-1)/(q-1)\) and \(C=\sum_Vf\). Then \(\sum_{H\ni x}Rf(H)=q^{n-1}f(x)+bC\), so \(f(x)=q^{1-n}(\sum_{H\ni x}Rf(H)-bC)\). The count uses \((q^n-1)/(q-1)\) hyperplanes through one point and \(b\) through two distinct points.',r'The identity is verified directly from the incidence counts on the page. Related finite integral geometry was developed in \citet[Theorems 1--2]{graevpavlenko1972radon}, submitted February 1972, for projective spaces over finite commutative rings; that is a related generalization, not an exact publication of this affine formula.',r'the inversion formula is established and elementary. The exact first publication of this notebook formulation was not identified. The fate classification records the later developed subject, without assigning priority.',**{'class':'B'},publication_match='partial',refs=['graevpavlenko1972radon'],confidence='medium',reconstruction=r'``Plane'' means hyperplane, as forced by the numerical coefficients; function values are taken in characteristic zero so division by \(q\) is valid.'),
I('P000368','claim','The range condition from parallel classes',r'The sum of \(\varphi(p)\) over each parallel class is the same constant \(C\), called a finite analogue of a Paley--Wiener condition.',r'Over \(\mathbb C\), the image of \(R\) consists exactly of functions \(\varphi\) on affine hyperplanes for which \(\sum_{H\parallel H_0}\varphi(H)\) is independent of the direction \(H_0\). Necessity follows by partitioning \(V\). For sufficiency, there are \(a=(q^n-1)/(q-1)\) parallel classes, each of size \(q\); the \(a-1\) independent equal-sum constraints leave dimension \(aq-(a-1)=q^n\), equal to the domain dimension, and the preceding inversion proves injectivity.',r'This is an editorial completion of the notebook’s elementary range observation. The projective transform in \citet{graevpavlenko1972radon} supplies related later development but has different range geometry; no exact source for this affine characterization was verified.',r'the range characterization is proved by the displayed finite-dimensional argument. It is not an unresolved Paley--Wiener problem.',**{'class':'B'},publication_match='thematic only',refs=['graevpavlenko1972radon'],confidence='medium',reconstruction=r'The sufficiency proof and its dimension count are supplied here; the page explicitly records only the equal-sum condition.'),
I('P000368','remark','Gaussian binomial coefficients and the limit q equals one',r'A remark attributed to Rota interprets \(C_k^n(q)\) as the number of \(k\)-dimensional subspaces and states its limit is \(\binom nk\).',r'The number of \(k\)-subspaces of \(\mathbb F_q^n\) is \(\genfrac{[}{]}{0pt}{}{n}{k}_q=\prod_{j=0}^{k-1}(q^{n-j}-1)/(q^{k-j}-1)\), a polynomial in \(q\) with integer coefficients. Its polynomial value at \(q=1\), equivalently the limit of this rational expression, is \(\binom nk\). It is a polynomial specialization, not a finite field with one element.',r'This finite-vector-space combinatorics is already developed in \citet{goldmanrota1970finite}, published September 1970, whose bibliography also records their 1969 subspace-count paper. Publisher metadata and references were checked; the collected full text exceeded the retrieval limit.',r'the identity is established. It explains the numerical coefficients in the preceding Radon argument.',verification='publisher metadata checked',refs=['goldmanrota1970finite'])
])
